{"command":"cat <<'EOF' > pkg/hostfile/hostfile.go
package hostfile

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

type Route struct {
	IP   string
	Host string
}

type Profile struct {
	Name   string
	Status string // "on" or "off"
	Routes []Route
}

type HostFile struct {
	FilePath       string
	UnmanagedLines []string
	Profiles       []*Profile
}

var Banner = []string{
	"##################################################################",
	"# Content under this line is handled by hostctl. DO NOT EDIT.",
	"##################################################################",
}

func Load(filePath string) (*HostFile, error) {
	f, err := os.Open(filePath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	hf := &HostFile{
		FilePath: filePath,
	}

	scanner := bufio.NewScanner(f)
	var currentProfile *Profile
	inManaged := false

	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)

		if strings.Contains(line, "Content under this line is handled by hostctl") {
			inManaged = true
			continue
		}

		if strings.HasPrefix(trimmed, "##################################################################") {
			inManaged = true
			continue
		}

		if strings.HasPrefix(trimmed, "# profile.on ") || strings.HasPrefix(trimmed, "# profile.off ") {
			inManaged = true
			parts := strings.Fields(trimmed)
			status := "on"
			if parts[0] == "#" && parts[1] == "profile.off" {
				status = "off"
			}
			profName := parts[len(parts)-1]
			currentProfile = &Profile{
				Name:   profName,
				Status: status,
			}
			hf.Profiles = append(hf.Profiles, currentProfile)
			continue
		}

		if currentProfile != nil && trimmed == "# end" {
			currentProfile = nil
			continue
		}

		if currentProfile != nil {
			l := trimmed
			if currentProfile.Status == "off" {
				if strings.HasPrefix(l, "#") {
					l = strings.TrimSpace(strings.TrimPrefix(l, "#"))
				}
			}
			if l == "" || strings.HasPrefix(l, "#") {
				continue
			}
			fields := strings.Fields(l)
			if len(fields) >= 2 {
				ip := fields[0]
				for _, host := range fields[1:] {
					if strings.HasPrefix(host, "#") {
						break
					}
					currentProfile.Routes = append(currentProfile.Routes, Route{
						IP:   ip,
						Host: host,
					})
				}
			}
			continue
		}

		if !inManaged {
			hf.UnmanagedLines = append(hf.UnmanagedLines, line)
		}
	}

	if err := scanner.Err(); err != nil {
		return nil, err
	}

	return hf, nil
}

func (hf *HostFile) GetDefaultProfile() *Profile {
	def := &Profile{
		Name:   "default",
		Status: "on",
	}
	for _, line := range hf.UnmanagedLines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		fields := strings.Fields(trimmed)
		if len(fields) >= 2 {
			ip := fields[0]
			host := fields[1]
			if !strings.HasPrefix(host, "#") {
				def.Routes = append(def.Routes, Route{
					IP:   ip,
					Host: host,
				})
			}
		}
	}
	return def
}

func (hf *HostFile) GetProfile(name string) *Profile {
	for _, p := range hf.Profiles {
		if p.Name == name {
			return p
		}
	}
	return nil
}

func (hf *HostFile) AddProfile(name string, routes []Route) *Profile {
	p := hf.GetProfile(name)
	if p == nil {
		p = &Profile{
			Name:   name,
			Status: "on",
			Routes: routes,
		}
		hf.Profiles = append(hf.Profiles, p)
	} else {
		for _, r := range routes {
			exists := false
			for _, er := range p.Routes {
				if er.IP == r.IP && er.Host == r.Host {
					exists = true
					break
				}
			}
			if !exists {
				p.Routes = append(p.Routes, r)
			}
		}
	}
	return p
}

func (hf *HostFile) ReplaceProfile(name string, routes []Route) *Profile {
	p := hf.GetProfile(name)
	if p == nil {
		p = &Profile{
			Name:   name,
			Status: "on",
			Routes: routes,
		}
		hf.Profiles = append(hf.Profiles, p)
	} else {
		p.Status = "on"
		p.Routes = routes
	}
	return p
}

func (hf *HostFile) EnableProfiles(names []string, all bool, only bool) ([]*Profile, error) {
	if all {
		for _, p := range hf.Profiles {
			p.Status = "on"
		}
		return hf.Profiles, nil
	}

	if only {
		for _, name := range names {
			if hf.GetProfile(name) == nil {
				return nil, fmt.Errorf("unknown profile name")
			}
		}
		for _, p := range hf.Profiles {
			p.Status = "off"
		}
		var modified []*Profile
		for _, name := range names {
			p := hf.GetProfile(name)
			p.Status = "on"
			modified = append(modified, p)
		}
		return modified, nil
	}

	for _, name := range names {
		if hf.GetProfile(name) == nil {
			return nil, fmt.Errorf("unknown profile name")
		}
	}
	var modified []*Profile
	for _, name := range names {
		p := hf.GetProfile(name)
		p.Status = "on"
		modified = append(modified, p)
	}
	return modified, nil
}

func (hf *HostFile) DisableProfiles(names []string, all bool, only bool) ([]*Profile, error) {
	if all {
		for _, p := range hf.Profiles {
			p.Status = "off"
		}
		return hf.Profiles, nil
	}

	if only {
		for _, name := range names {
			if hf.GetProfile(name) == nil {
				return nil, fmt.Errorf("unknown profile name")
			}
		}
		for _, p := range hf.Profiles {
			p.Status = "on"
		}
		var modified []*Profile
		for _, name := range names {
			p := hf.GetProfile(name)
			p.Status = "off"
			modified = append(modified, p)
		}
		return modified, nil
	}

	for _, name := range names {
		if hf.GetProfile(name) == nil {
			return nil, fmt.Errorf("unknown profile name")
		}
	}
	var modified []*Profile
	for _, name := range names {
		p := hf.GetProfile(name)
		p.Status = "off"
		modified = append(modified, p)
	}
	return modified, nil
}

func (hf *HostFile) ToggleProfiles(names []string) ([]*Profile, error) {
	for _, name := range names {
		if hf.GetProfile(name) == nil {
			return nil, fmt.Errorf("unknown profile name")
		}
	}
	var modified []*Profile
	for _, name := range names {
		p := hf.GetProfile(name)
		if p.Status == "on" {
			p.Status = "off"
		} else {
			p.Status = "on"
		}
		modified = append(modified, p)
	}
	return modified, nil
}

func (hf *HostFile) RemoveProfiles(names []string, all bool) ([]string, error) {
	if all {
		if len(hf.Profiles) == 0 {
			return nil, fmt.Errorf("there are no profiles")
		}
		var removed []string
		for _, p := range hf.Profiles {
			removed = append(removed, p.Name)
		}
		hf.Profiles = nil
		return removed, nil
	}

	for _, name := range names {
		if hf.GetProfile(name) == nil {
			return nil, fmt.Errorf("unknown profile name")
		}
	}

	var newProfs []*Profile
	for _, p := range hf.Profiles {
		keep := true
		for _, name := range names {
			if p.Name == name {
				keep = false
				break
			}
		}
		if keep {
			newProfs = append(newProfs, p)
		}
	}
	hf.Profiles = newProfs
	return names, nil
}

func (hf *HostFile) AddDomains(profileName string, ip string, domains []string) (*Profile, error) {
	p := hf.GetProfile(profileName)
	if p == nil {
		p = &Profile{
			Name:   profileName,
			Status: "on",
		}
		hf.Profiles = append(hf.Profiles, p)
	}
	for _, dom := range domains {
		exists := false
		for _, r := range p.Routes {
			if r.IP == ip && r.Host == dom {
				exists = true
				break
			}
		}
		if !exists {
			p.Routes = append(p.Routes, Route{
				IP:   ip,
				Host: dom,
			})
		}
	}
	return p, nil
}

func (hf *HostFile) RemoveDomains(profileName string, domains []string) (*Profile, error) {
	p := hf.GetProfile(profileName)
	if p == nil {
		return nil, fmt.Errorf("unknown profile name")
	}
	domMap := make(map[string]bool)
	for _, d := range domains {
		domMap[d] = true
	}
	var newRoutes []Route
	for _, r := range p.Routes {
		if !domMap[r.Host] {
			newRoutes = append(newRoutes, r)
		}
	}
	p.Routes = newRoutes
	return p, nil
}

func (hf *HostFile) Save() error {
	var sb strings.Builder

	// Trim trailing empty lines from unmanaged
	lines := hf.UnmanagedLines
	for len(lines) > 0 && strings.TrimSpace(lines[len(lines)-1]) == "" {
		lines = lines[:len(lines)-1]
	}
	for _, l := range lines {
		sb.WriteString(l)
		sb.WriteString("\n")
	}
	sb.WriteString("\n")

	for _, b := range Banner {
		sb.WriteString(b)
		sb.WriteString("\n")
	}

	for _, p := range hf.Profiles {
		sb.WriteString("\n")
		sb.WriteString(fmt.Sprintf("# profile.%s %s\n", p.Status, p.Name))
		for _, r := range p.Routes {
			if p.Status == "on" {
				sb.WriteString(fmt.Sprintf("%s %s\n", r.IP, r.Host))
			} else {
				sb.WriteString(fmt.Sprintf("# %s %s\n", r.IP, r.Host))
			}
		}
		sb.WriteString("# end\n")
	}

	return os.WriteFile(hf.FilePath, []byte(sb.String()), 0644)
}

func ParseSourceFile(filePath string) ([]Route, error) {
	var f *os.File
	var err error
	if filePath == "-" || filePath == "/dev/stdin" {
		f = os.Stdin
	} else {
		f, err = os.Open(filePath)
		if err != nil {
			return nil, err
		}
		defer f.Close()
	}

	scanner := bufio.NewScanner(f)
	var routes []Route
	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		fields := strings.Fields(trimmed)
		if len(fields) >= 2 {
			ip := fields[0]
			for _, host := range fields[1:] {
				if strings.HasPrefix(host, "#") {
					break
				}
				routes = append(routes, Route{
					IP:   ip,
					Host: host,
				})
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return routes, nil
}
EOF"}

{"command":"cat <<'EOF' > pkg/render/render.go
package render

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"golang.org/x/term"
)

type Opts struct {
	Out      string
	Columns  []string
	Quiet    bool
	NoColor  bool
	IsStatus bool
}

type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

type JsonRow struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

func isColorEnabled(noColor bool) bool {
	if noColor {
		return false
	}
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	return term.IsTerminal(int(os.Stdout.Fd()))
}

func PrintInfo(opts *Opts, msg string) {
	if opts.Quiet || opts.Out == "json" {
		return
	}
	icon := "ℹ"
	if isColorEnabled(opts.NoColor) {
		icon = "\x1b[1;36m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] %s\n\n", icon, msg)
}

func PrintSuccess(opts *Opts, msg string) {
	if opts.Quiet {
		return
	}
	icon := "✔"
	if isColorEnabled(opts.NoColor) {
		icon = "\x1b[1;32m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] %s\n\n", icon, msg)
}

func PrintError(err error, noColor bool) {
	icon := "✖"
	if isColorEnabled(noColor) {
		icon = "\x1b[1;31m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] error: %s\n", icon, err.Error())
}

func PrintTable(opts *Opts, rows []Row) {
	if opts.Quiet {
		return
	}

	if opts.Out == "json" {
		jsonRows := make([]JsonRow, 0, len(rows))
		for _, r := range rows {
			if opts.IsStatus {
				jsonRows = append(jsonRows, JsonRow{
					Profile: r.Profile,
					Status:  r.Status,
					IP:      "",
					Host:    "",
				})
			} else {
				jsonRows = append(jsonRows, JsonRow{
					Profile: r.Profile,
					Status:  r.Status,
					IP:      r.IP,
					Host:    r.Host,
				})
			}
		}
		data, _ := json.Marshal(jsonRows)
		fmt.Println(string(data))
		return
	}

	if len(rows) == 0 {
		return
	}

	// Filter columns
	var cols []string
	if len(opts.Columns) > 0 {
		for _, c := range opts.Columns {
			lc := strings.ToLower(c)
			if lc == "profile" || lc == "status" || lc == "ip" || lc == "domain" {
				cols = append(cols, lc)
			}
		}
	}
	if len(cols) == 0 {
		if opts.IsStatus {
			cols = []string{"profile", "status"}
		} else {
			cols = []string{"profile", "status", "ip", "domain"}
		}
	}

	// Compute widths
	colWidths := make([]int, len(cols))
	headers := make([]string, len(cols))
	for i, col := range cols {
		headers[i] = strings.ToUpper(col)
		colWidths[i] = len(headers[i])
	}

	for _, r := range rows {
		for i, col := range cols {
			val := getVal(r, col)
			if len(val) > colWidths[i] {
				colWidths[i] = len(val)
			}
		}
	}

	switch opts.Out {
	case "raw":
		// Header
		for i, h := range headers {
			fmt.Printf("%s\t", padRight(h, colWidths[i]))
		}
		fmt.Println()
		// Rows
		for _, r := range rows {
			for i, col := range cols {
				val := getVal(r, col)
				fmt.Printf("%s\t", padRight(val, colWidths[i]))
			}
			fmt.Println()
		}

	case "markdown":
		// Header
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", center(h, colWidths[i]))
		}
		fmt.Println()
		// Delimiter
		fmt.Print("|")
		for _, w := range colWidths {
			fmt.Printf("%s|", strings.Repeat("-", w+2))
		}
		fmt.Println()
		// Rows
		var prevProfile string
		for idx, r := range rows {
			if idx > 0 && r.Profile != prevProfile {
				fmt.Print("|")
				for _, w := range colWidths {
					fmt.Printf("%s|", strings.Repeat("-", w+2))
				}
				fmt.Println()
			}
			prevProfile = r.Profile

			fmt.Print("|")
			for i, col := range cols {
				val := getVal(r, col)
				fmt.Printf(" %s |", padRight(val, colWidths[i]))
			}
			fmt.Println()
		}

	default: // "table"
		makeBorder := func() string {
			var b strings.Builder
			b.WriteString("+")
			for _, w := range colWidths {
				b.WriteString(strings.Repeat("-", w+2))
				b.WriteString("+")
			}
			return b.String()
		}

		border := makeBorder()
		fmt.Println(border)

		// Header
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", center(h, colWidths[i]))
		}
		fmt.Println()
		fmt.Println(border)

		// Rows
		var prevProfile string
		for idx, r := range rows {
			if idx > 0 && r.Profile != prevProfile {
				fmt.Println(border)
			}
			prevProfile = r.Profile

			fmt.Print("|")
			for i, col := range cols {
				val := getVal(r, col)
				fmt.Printf(" %s |", padRight(val, colWidths[i]))
			}
			fmt.Println()
		}
		fmt.Println(border)
	}
}

func getVal(r Row, col string) string {
	switch col {
	case "profile":
		return r.Profile
	case "status":
		return r.Status
	case "ip":
		return r.IP
	case "domain":
		return r.Host
	}
	return ""
}

func center(s string, width int) string {
	padding := width - len(s)
	if padding <= 0 {
		return s
	}
	left := padding / 2
	right := padding - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}
EOF"}

