	Long: `hostctl is a CLI tool to manage your hosts file with ease.
You can have multiple profiles, enable/disable exactly what
you need each time with a simple interface.`,
	SilenceUsage:  true,
	SilenceErrors: true,
	RunE: func(cmd *cobra.Command, args []string) error {
		if version {
			fmt.Println("hostctl version dev")
			return nil
		}
		return cmd.Help()
	},
}

func Execute() {
	if err := rootCmd.Execute(); err != nil {
		render.PrintError(err, noColor)
		os.Exit(1)
	}
}

func init() {
	rootCmd.Version = "dev"
	rootCmd.SetVersionTemplate("hostctl version {{.Version}}\n")

	rootCmd.PersistentFlags().StringVar(&hostFile, "host-file", "/etc/hosts", "Hosts file path")
	rootCmd.PersistentFlags().StringVarP(&out, "out", "o", "table", "Output type (table|raw|markdown|json)")
	rootCmd.PersistentFlags().BoolVarP(&quiet, "quiet", "q", false, "Run command without output")
	rootCmd.PersistentFlags().BoolVar(&raw, "raw", false, "Output without borders (same as -o raw)")
	rootCmd.PersistentFlags().BoolVar(&noColor, "no-color", false, "force colorless output")
	rootCmd.PersistentFlags().StringSliceVarP(&columns, "column", "c", nil, "Column names to show on lists. comma separated")
	rootCmd.Flags().BoolVarP(&version, "version", "v", false, "version for hostctl")

	rootCmd.AddCommand(listCmd)
	rootCmd.AddCommand(statusCmd)
	rootCmd.AddCommand(enableCmd)
	rootCmd.AddCommand(disableCmd)
	rootCmd.AddCommand(toggleCmd)
	rootCmd.AddCommand(removeCmd)
	rootCmd.AddCommand(addCmd)
	rootCmd.AddCommand(replaceCmd)
	rootCmd.AddCommand(backupCmd)
	rootCmd.AddCommand(restoreCmd)
	rootCmd.AddCommand(syncCmd)
}

func getRenderOpts() *render.Opts {
	o := out
	if raw {
		o = "raw"
	}
	return &render.Opts{
		Out:     o,
		Columns: columns,
		Quiet:   quiet,
		NoColor: noColor,
	}
}

func checkHostFileNotice(opts *render.Opts) {
	if hostFile != "/etc/hosts" {
		render.PrintInfo(opts, fmt.Sprintf("Using hosts file: %s", hostFile))
	}
}

func profilesToRows(profs []*hostfile.Profile) []render.Row {
	var rows []render.Row
	for _, p := range profs {
		for _, r := range p.Routes {
			rows = append(rows, render.Row{
				Profile: p.Name,
				Status:  p.Status,
				IP:      r.IP,
				Host:    r.Host,
			})
		}
	}
	return rows
}

func profileToRows(p *hostfile.Profile) []render.Row {
	if p == nil {
		return nil
	}
	return profilesToRows([]*hostfile.Profile{p})
}

func waitForSignal(d time.Duration) {
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	select {
	case <-time.After(d):
	case <-sigChan:
	}
}
