	"github.com/guumaster/hostctl/pkg/render"
	"github.com/spf13/cobra"
)

var listCmd = &cobra.Command{
	Use:   "list [profiles]",
	Short: "Shows a detailed list of profiles on your hosts file.",
	Long: `Shows a detailed list of profiles on your hosts file with name, ip and host name.
You can filter by profile name.

The "default" profile is all the content that is not handled by hostctl tool.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		rows := getRowsForList(hf, args, "all")
		render.PrintTable(opts, rows)
		return nil
	},
}

var listDisabledCmd = &cobra.Command{
	Use:     "disabled",
	Aliases: []string{"off"},
	Short:   "Shows list of disabled profiles on your hosts file.",
	Long:    `Shows a detailed list of disabled profiles on your hosts file with name, ip and host name.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		rows := getRowsForList(hf, args, "off")
		render.PrintTable(opts, rows)
		return nil
	},
}

var listEnabledCmd = &cobra.Command{
	Use:     "enabled",
	Aliases: []string{"on"},
	Short:   "Shows list of enabled profiles on your hosts file.",
	Long:    `Shows a detailed list of enabled profiles on your hosts file with name, ip and host name.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		rows := getRowsForList(hf, args, "on")
		render.PrintTable(opts, rows)
		return nil
	},
}

func init() {
	listCmd.AddCommand(listDisabledCmd)
	listCmd.AddCommand(listEnabledCmd)
}

func getRowsForList(hf *hostfile.HostFile, filterProfiles []string, filterStatus string) []render.Row {
	var rows []render.Row

	if len(filterProfiles) == 0 {
		def := hf.GetDefaultProfile()
		if len(def.Routes) > 0 {
			for _, r := range def.Routes {
				rows = append(rows, render.Row{
					Profile: def.Name,
					Status:  def.Status,
					IP:      r.IP,
					Host:    r.Host,
				})
			}
		}
		for _, p := range hf.Profiles {
			if filterStatus == "all" || p.Status == filterStatus {
				for _, r := range p.Routes {
					rows = append(rows, render.Row{
						Profile: p.Name,
						Status:  p.Status,
						IP:      r.IP,
						Host:    r.Host,
					})
				}
			}
		}
	} else {
		for _, name := range filterProfiles {
			if name == "default" {
				def := hf.GetDefaultProfile()
				if len(def.Routes) > 0 {
					for _, r := range def.Routes {
						rows = append(rows, render.Row{
							Profile: def.Name,
							Status:  def.Status,
							IP:      r.IP,
							Host:    r.Host,
						})
					}
				}
			} else {
				p := hf.GetProfile(name)
				if p != nil && (filterStatus == "all" || p.Status == filterStatus) {
					for _, r := range p.Routes {
						rows = append(rows, render.Row{
							Profile: p.Name,
							Status:  p.Status,
							IP:      r.IP,
							Host:    r.Host,
						})
					}
				}
			}
		}
	}

	return rows
}
EOF

