{"command":"cat <<'EOF' > cmd/enable.go
package cmd

import (
	"fmt"
	"strings"
	"time"

	"github.com/guumaster/hostctl/pkg/hostfile"
	"github.com/guumaster/hostctl/pkg/render"
	"github.com/spf13/cobra"
)

var (
	enableAll  bool
	enableOnly bool
	enableWait time.Duration
)

var enableCmd = &cobra.Command{
	Use:   "enable [profiles]",
	Short: "Enable a profile on your hosts file.",
	Long:  `Enables an existing profile.
It will be listed as "on" while it is enabled.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if !enableAll && len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		for _, name := range args {
			if name == "default" {
				return fmt.Errorf("'default' profile should not be handled by hostctl")
			}
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		modified, err := hf.EnableProfiles(args, enableAll, enableOnly)
		if err != nil {
			return err
		}

		if err := hf.Save(); err != nil {
			return err
		}

		rows := profilesToRows(modified)
		render.PrintTable(opts, rows)

		if enableWait > 0 {
			profStr := strings.Join(args, ", ")
			render.PrintInfo(opts, fmt.Sprintf("Waiting for %s or ctrl+c to disable from profile '%s'", enableWait, profStr))
			waitForSignal(enableWait)

			hf, err := hostfile.Load(hostFile)
			if err != nil {
				return err
			}
			reverted, err := hf.DisableProfiles(args, enableAll, enableOnly)
			if err != nil {
				return err
			}
			if err := hf.Save(); err != nil {
				return err
			}
			render.PrintTable(opts, profilesToRows(reverted))
		}

		return nil
	},
}

func init() {
	enableCmd.Flags().BoolVar(&enableAll, "all", false, "Enable all profiles")
	enableCmd.Flags().BoolVar(&enableOnly, "only", false, "Disable all other profiles")
	enableCmd.Flags().DurationVarP(&enableWait, "wait", "w", -1, "Enables a profile for a specific amount of time")
}
EOF

