package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/guumaster/hostctl/pkg/hostfile"
	"github.com/guumaster/hostctl/pkg/render"
	"github.com/spf13/cobra"
)

var backupPath string

var backupCmd = &cobra.Command{
	Use:   "backup",
	Short: "Creates a backup copy of your hosts file",
	Long: `Creates a backup copy of your hosts file with the date in .YYYYMMDD
as extension.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		dir := backupPath
		if dir == "" {
			dir, _ = os.Getwd()
		}

		ext := time.Now().Format("20060102")
		base := filepath.Base(hostFile)
		backupFile := filepath.Join(dir, fmt.Sprintf("%s.%s", base, ext))

		content, err := os.ReadFile(hostFile)
		if err != nil {
			return err
		}

		if err := os.WriteFile(backupFile, content, 0644); err != nil {
			return err
		}

		render.PrintSuccess(opts, fmt.Sprintf("Backup '%s' created.", backupFile))

		rows := getRowsForList(hf, nil, "all")
		render.PrintTable(opts, rows)
		return nil
	},
}

func init() {
	cwd, _ := os.Getwd()
	backupCmd.Flags().StringVar(&backupPath, "path", cwd, "A path to save the backup")
}
EOF

