cat <<'EOF' > cmd/sync.go
package cmd

import (
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/guumaster/hostctl/pkg/hostfile"
	"github.com/guumaster/hostctl/pkg/render"
	"github.com/spf13/cobra"
)

var (
	syncWait time.Duration

	syncDockerDomain  string
	syncDockerNetwork string

	syncComposeFile        string
	syncComposeDomain      string
	syncComposeNetwork     string
	syncComposePrefix      bool
	syncComposeProjectName string
)

var syncCmd = &cobra.Command{
	Use:   "sync [command]",
	Short: "Sync some system IPs with a profile.",
	Long:  `Reads IPs and names from some local system and sync it with a profile in your hosts file.`,
}

var syncDockerCmd = &cobra.Command{
	Use:   "docker [profile]",
	Short: "Sync your Docker containers IPs with a profile.",
	Long:  `Reads from Docker the list of containers and add names and IPs to a profile in your hosts file.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		if len(args) > 1 {
			return fmt.Errorf("specify only one profile")
		}
		profName := args[0]
		if profName == "default" {
			return fmt.Errorf("'default' profile should not be handled by hostctl")
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		// Docker sync requires Docker daemon connection
		return fmt.Errorf("Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?")
	},
}

var syncComposeCmd = &cobra.Command{
	Use:   "docker-compose [profile]",
	Short: "Sync your docker-compose containers IPs with a profile.",
	Long:  `Reads from a docker-compose.yml file  the list of containers and add names and IPs to a profile in your hosts file.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		if len(args) > 1 {
			return fmt.Errorf("specify only one profile")
		}
		profName := args[0]
		if profName == "default" {
			return fmt.Errorf("'default' profile should not be handled by hostctl")
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		composePath := syncComposeFile
		if composePath == "" {
			cwd, _ := os.Getwd()
			composePath = filepath.Join(cwd, "docker-compose.yml")
		}

		if _, err := os.Stat(composePath); err != nil {
			return err
		}

		return fmt.Errorf("Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?")
	},
}

func init() {
	syncCmd.PersistentFlags().DurationVarP(&syncWait, "wait", "w", -1, "Enables a profile for a specific amount of time")

	syncDockerCmd.Flags().StringVarP(&syncDockerDomain, "domain", "d", "loc", "domain where your docker containers will be added")
	syncDockerCmd.Flags().StringVar(&syncDockerNetwork, "network", "", "Filter containers from a specific network")

	syncComposeCmd.Flags().StringVar(&syncComposeFile, "compose-file", "", "path to docker-compose.yml")
	syncComposeCmd.Flags().StringVarP(&syncComposeDomain, "domain", "d", "loc", "domain where your docker containers will be added")
	syncComposeCmd.Flags().StringVar(&syncComposeNetwork, "network", "", "Filter containers from a specific network")
	syncComposeCmd.Flags().BoolVar(&syncComposePrefix, "prefix", false, "keep project name prefix from domain name")
	syncComposeCmd.Flags().StringVar(&syncComposeProjectName, "project-name", "", "docker compose project name")

	syncCmd.AddCommand(syncDockerCmd)
	syncCmd.AddCommand(syncComposeCmd)
}
EOF"}

