	"strings"
	"syscall"
	"unsafe"
)

type Opts struct {
	Out      string
	Columns  []string
	Quiet    bool
	NoColor  bool
	IsStatus bool
}

type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

type JsonRow struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func isColorEnabled(noColor bool) bool {
	if noColor {
		return false
	}
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	return isTerminal(os.Stdout.Fd())
}

func PrintInfo(opts *Opts, msg string) {
	if opts.Quiet || opts.Out == "json" {
		return
	}
	icon := "ℹ"
	if isColorEnabled(opts.NoColor) {
		icon = "\x1b[1;36m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] %s\n\n", icon, msg)
}

func PrintSuccess(opts *Opts, msg string) {
	if opts.Quiet {
		return
	}
	icon := "✔"
	if isColorEnabled(opts.NoColor) {
		icon = "\x1b[1;32m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] %s\n\n", icon, msg)
}

func PrintError(err error, noColor bool) {
	icon := "✖"
	if isColorEnabled(noColor) {
		icon = "\x1b[1;31m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] error: %s\n", icon, err.Error())
}

func PrintTable(opts *Opts, rows []Row) {
	if opts.Quiet {
		return
	}

	if opts.Out == "json" {
		jsonRows := make([]JsonRow, 0, len(rows))
		for _, r := range rows {
			if opts.IsStatus {
				jsonRows = append(jsonRows, JsonRow{
					Profile: r.Profile,
					Status:  r.Status,
					IP:      "",
					Host:    "",
				})
			} else {
				jsonRows = append(jsonRows, JsonRow{
					Profile: r.Profile,
					Status:  r.Status,
					IP:      r.IP,
					Host:    r.Host,
				})
			}
		}
		data, _ := json.Marshal(jsonRows)
		fmt.Println(string(data))
		return
	}

	if len(rows) == 0 {
		return
	}

	// Filter columns
	var cols []string
	if len(opts.Columns) > 0 {
		for _, c := range opts.Columns {
			lc := strings.ToLower(c)
			if lc == "profile" || lc == "status" || lc == "ip" || lc == "domain" {
				cols = append(cols, lc)
			}
		}
	}
	if len(cols) == 0 {
		if opts.IsStatus {
			cols = []string{"profile", "status"}
		} else {
			cols = []string{"profile", "status", "ip", "domain"}
		}
	}

	// Compute widths
	colWidths := make([]int, len(cols))
	headers := make([]string, len(cols))
	for i, col := range cols {
		headers[i] = strings.ToUpper(col)
		colWidths[i] = len(headers[i])
	}

	for _, r := range rows {
		for i, col := range cols {
			val := getVal(r, col)
			if len(val) > colWidths[i] {
				colWidths[i] = len(val)
			}
		}
	}

	switch opts.Out {
	case "raw":
		// Header
		for i, h := range headers {
			fmt.Printf("%s\t", padRight(h, colWidths[i]))
		}
		fmt.Println()
		// Rows
		for _, r := range rows {
			for i, col := range cols {
				val := getVal(r, col)
				fmt.Printf("%s\t", padRight(val, colWidths[i]))
			}
			fmt.Println()
		}

	case "markdown":
		// Header
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", center(h, colWidths[i]))
		}
		fmt.Println()
		// Delimiter
		fmt.Print("|")
		for _, w := range colWidths {
			fmt.Printf("%s|", strings.Repeat("-", w+2))
		}
		fmt.Println()
		// Rows
		var prevProfile string
		for idx, r := range rows {
			if idx > 0 && r.Profile != prevProfile {
				fmt.Print("|")
				for _, w := range colWidths {
					fmt.Printf("%s|", strings.Repeat("-", w+2))
				}
				fmt.Println()
			}
			prevProfile = r.Profile

			fmt.Print("|")
			for i, col := range cols {
				val := getVal(r, col)
				fmt.Printf(" %s |", padRight(val, colWidths[i]))
			}
			fmt.Println()
		}

	default: // "table"
		makeBorder := func() string {
			var b strings.Builder
			b.WriteString("+")
			for _, w := range colWidths {
				b.WriteString(strings.Repeat("-", w+2))
				b.WriteString("+")
			}
			return b.String()
		}

		border := makeBorder()
		fmt.Println(border)

		// Header
		fmt.Print("|")
		for i, h := range headers {
			fmt.Printf(" %s |", center(h, colWidths[i]))
		}
		fmt.Println()
		fmt.Println(border)

		// Rows
		var prevProfile string
		for idx, r := range rows {
			if idx > 0 && r.Profile != prevProfile {
				fmt.Println(border)
			}
			prevProfile = r.Profile

			fmt.Print("|")
			for i, col := range cols {
				val := getVal(r, col)
				fmt.Printf(" %s |", padRight(val, colWidths[i]))
			}
			fmt.Println()
		}
		fmt.Println(border)
	}
}

func getVal(r Row, col string) string {
	switch col {
	case "profile":
		return r.Profile
	case "status":
		return r.Status
	case "ip":
		return r.IP
	case "domain":
		return r.Host
	}
	return ""
}

func center(s string, width int) string {
	padding := width - len(s)
	if padding <= 0 {
		return s
	}
	left := padding / 2
	right := padding - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}
EOF"}

