	RunE: func(cmd *cobra.Command, args []string) error {
		if len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		if len(args) > 1 {
			return fmt.Errorf("specify only one profile")
		}
		profName := args[0]
		if profName == "default" {
			return fmt.Errorf("'default' profile should not be handled by hostctl")
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		composePath := syncComposeFile
		if composePath == "" {
			cwd, _ := os.Getwd()
			composePath = filepath.Join(cwd, "docker-compose.yml")
		}

		if _, err := os.Stat(composePath); err != nil {
			return err
		}

		return fmt.Errorf("Cannot connect to the Docker daemon at unix:///var/run/docker.sock. Is the docker daemon running?")
	},
}

func init() {
	syncCmd.PersistentFlags().DurationVarP(&syncWait, "wait", "w", -1, "Enables a profile for a specific amount of time")

	syncDockerCmd.Flags().StringVarP(&syncDockerDomain, "domain", "d", "loc", "domain where your docker containers will be added")
	syncDockerCmd.Flags().StringVar(&syncDockerNetwork, "network", "", "Filter containers from a specific network")

