	syncComposeCmd.Flags().StringVarP(&syncComposeDomain, "domain", "d", "loc", "domain where your docker containers will be added")
	syncComposeCmd.Flags().StringVar(&syncComposeNetwork, "network", "", "Filter containers from a specific network")
	syncComposeCmd.Flags().BoolVar(&syncComposePrefix, "prefix", false, "keep project name prefix from domain name")
	syncComposeCmd.Flags().StringVar(&syncComposeProjectName, "project-name", "", "docker compose project name")

	syncCmd.AddCommand(syncDockerCmd)
	syncCmd.AddCommand(syncComposeCmd)
}
EOF"}

