If you want to remove a profile but would like to use it later,
use 'hosts disable' instead.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if !removeAll && len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		for _, name := range args {
			if name == "default" {
				return fmt.Errorf("'default' profile should not be handled by hostctl")
			}
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		removed, err := hf.RemoveProfiles(args, removeAll)
		if err != nil {
			return err
		}

		if err := hf.Save(); err != nil {
			return err
		}

		render.PrintSuccess(opts, fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(removed, ", ")))
		if !opts.Quiet {
			fmt.Println()
		}
		return nil
	},
}

var removeDomainsCmd = &cobra.Command{
	Use:     "domains [profile] [domains]",
	Aliases: []string{"domain"},
	Short:   "Remove domains from your hosts file.",
	Long:    `Completely remove domains from your hosts file.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		profName := args[0]
		if profName == "default" {
			return fmt.Errorf("'default' profile should not be handled by hostctl")
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		doms := args[1:]
		if len(doms) == 0 {
			_, err := hf.RemoveProfiles([]string{profName}, false)
			if err != nil {
				return err
			}
			if err := hf.Save(); err != nil {
				return err
			}
