var addCmd = &cobra.Command{
	Use:   "add [profiles]",
	Short: "Add content to a profile in your hosts file.",
	Long: `Reads from a file and set content to a profile in your hosts file.
If the profile already exists it will be added to it.`,
	RunE: func(cmd *cobra.Command, args []string) error {
		if len(args) == 0 {
			return fmt.Errorf("missing profile name")
		}
		if len(args) > 1 {
			return fmt.Errorf("specify only one profile")
		}
		profName := args[0]
		if profName == "default" {
			return fmt.Errorf("'default' profile should not be handled by hostctl")
		}

		opts := getRenderOpts()
		checkHostFileNotice(opts)

		routes, err := hostfile.ParseSourceFile(addFrom)
		if err != nil {
			return err
		}

		hf, err := hostfile.Load(hostFile)
		if err != nil {
			return err
		}

		prof := hf.AddProfile(profName, routes)
		if err := hf.Save(); err != nil {
			return err
		}

		render.PrintTable(opts, profileToRows(prof))
		if !opts.Quiet {
			fmt.Println()
		}

		if addWait > 0 {
			render.PrintInfo(opts, fmt.Sprintf("Waiting for %s or ctrl+c to remove from profile '%s'", addWait, profName))
			waitForSignal(addWait)

			hf, err := hostfile.Load(hostFile)
			if err != nil {
				return err
			}
			_, err = hf.RemoveProfiles([]string{profName}, false)
			if err != nil {
				return err
			}
			if err := hf.Save(); err != nil {
				return err
			}
			render.PrintSuccess(opts, fmt.Sprintf("Profile(s) '%s' removed.", profName))
			if !opts.Quiet {
				fmt.Println()
			}
		}

		return nil
	},
}

var addDomainsCmd = &cobra.Command{
	Use:     "domains [profile] [domains]",
	Aliases: []string{"domain"},
	Short:   "Add content in your hosts file.",
	Long:    `Set content in your hosts file.`,
