{"command":"cat <<'EOF' > pkg/render/render.go
package render

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"syscall"
	"unsafe"
)

type Opts struct {
	Out      string
	Columns  []string
	Quiet    bool
	NoColor  bool
	IsStatus bool
}

type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

type JsonRow struct {
	Profile string `json:"Profile"`
	Status  string `json:"Status"`
	IP      string `json:"IP"`
	Host    string `json:"Host"`
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return err == 0
}

func isColorEnabled(noColor bool) bool {
	if noColor {
		return false
	}
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	return isTerminal(os.Stdout.Fd())
}

func PrintInfo(opts *Opts, msg string) {
	if opts.Quiet || opts.Out == "json" {
		return
	}
	icon := "ℹ"
	if isColorEnabled(opts.NoColor) {
		icon = "\x1b[1;36m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] %s\n\n", icon, msg)
}

func PrintSuccess(opts *Opts, msg string) {
	if opts.Quiet {
		return
	}
	icon := "✔"
	if isColorEnabled(opts.NoColor) {
		icon = "\x1b[1;32m" + icon + "\x1b[0m"
	}
	fmt.Printf("[%s] %s\n\n", icon, msg)
}

func PrintError(err error, noColor bool) {
	icon := "✖"
	if isColorEnabled(noColor) {
		icon = "\x1b[1;31m" + icon + "\x1b[0m"
